// Rules, in order:
//  P1 checks[] present and non-empty
//  P2 every check has a unique, non-empty id and a type
//  P3 placeholder closure BOTH ways: every {{binding.x}} is declared in
//     binding_schema, and every declared binding is used by some check
//  P4 no absolute URL, and no literal in a selector/path/url field, unless the
//     check carries literal_ok with a reason (bugs_closed/045)
//  P5 unknown check type -> DEFERRED if marked _unsupported/deferred with a
//     reason, else an ERROR naming the tier tables
//  P6 fields the checkers never read (expect_within_ms, retries, after, equals,
//     min) -> same rule: a check carrying one asserts less than it appears to
//  P7 step actions outside fill|click|select -> same rule
//  P8 expect keys outside selector|text_matches -> same rule
//  P9 an id containing "-EDIT" is rejected outright: Tier 2 SKIPS those
//     silently, so an unfilled template reads green

func TestExperienceCheckCapabilities_LockstepWithCheckers(t *testing.T) {
    tier2 := caseLabelsIn(t, "discovery_checks/check_tool_acceptance.go")
    tier4 := caseLabelsIn(t, "../../../internal/adapters/browserrunner/run_checks_action.go")
    for typ, tier := range experienceCheckTiers {
        src := tier2; if tier == 4 { src = tier4 }
        if !src[typ] { t.Errorf("the table says %q runs at tier %d but %s does not implement it", typ, tier, ...) }
    }
    for typ := range tier4 {                       // the reverse direction is the one that rots
        if _, known := experienceCheckTiers[typ]; !known {
            t.Errorf("the browser runner implements %q but the validator's table does not know it", typ)
        }
    }
}
